//! The user-global Git baseline owned by ghis.
//!
//! `ghis gitconfig setup` adds exactly one `include.path` value to the user's
//! global Git configuration and points it at a generated file.  The file turns
//! off Git's automatic identity detection, so a repository that ghis has not
//! bound cannot commit with an invented author.  Every identity-plane setting
//! must then come from a Profile fragment.
//!
//! Only that one include entry belongs to ghis.  Everything else in the global
//! file is left byte-for-byte alone, and `uninstall` removes only the entry
//! whose value is ghis's own path.

use crate::config::ConfigPaths;
use crate::git;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

pub const INCLUDE_KEY: &str = "include.path";

#[derive(Debug, thiserror::Error)]
pub enum BaselineError {
    #[error("{0}")]
    Io(#[from] io::Error),
    #[error("无法运行 git {operation}：{detail}")]
    Git { operation: String, detail: String },
}

pub type Result<T> = std::result::Result<T, BaselineError>;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BaselineStatus {
    pub path: PathBuf,
    /// Number of global `include.path` entries that point at ghis's file.
    pub include_count: usize,
    pub file_exists: bool,
    /// Whether the file on disk is exactly what this version generates.
    pub file_current: bool,
}

impl BaselineStatus {
    pub fn installed(&self) -> bool {
        self.include_count > 0
    }

    pub fn up_to_date(&self) -> bool {
        self.include_count == 1 && self.file_current
    }
}

/// The generated file is shared by every `--config` namespace: the global
/// baseline is a property of the machine, not of one ghis configuration.
pub fn baseline_path(paths: &ConfigPaths) -> PathBuf {
    paths.config_dir.join("global.gitconfig")
}

/// The baseline deliberately carries no identity.  `useConfigOnly` makes Git
/// abort instead of deriving `user@host` from the system when a repository has
/// no Profile fragment.
pub fn render() -> String {
    let mut output = String::new();
    output.push_str("# Generated by ghis; edits may be overwritten.\n");
    output.push_str("# Run `ghis gitconfig uninstall` to remove this include.\n");
    output.push_str("[user]\n");
    output.push_str("\tuseConfigOnly = true\n");
    output
}

pub fn status(paths: &ConfigPaths) -> Result<BaselineStatus> {
    let path = baseline_path(paths);
    let include_count = includes(paths, &path)?.len();
    let file_current = fs::read_to_string(&path)
        .map(|content| content == render())
        .unwrap_or(false);
    let file_exists = path.exists();
    Ok(BaselineStatus {
        path,
        include_count,
        file_exists,
        file_current,
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct InstallOutcome {
    pub file_changed: bool,
    pub include_changed: bool,
}

/// Write the baseline file and make sure the global configuration includes it.
/// Idempotent: a second run changes nothing, and duplicate entries that point
/// at ghis's own path are collapsed back to one.
pub fn install(paths: &ConfigPaths) -> Result<InstallOutcome> {
    fs::create_dir_all(&paths.config_dir)?;
    let path = baseline_path(paths);
    let content = render();
    let file_changed = fs::read_to_string(&path).ok().as_deref() != Some(content.as_str());
    if file_changed {
        write_atomically(&path, &content)?;
    }

    let matches = includes(paths, &path)?;
    let include_changed = if matches.len() == 1 {
        false
    } else {
        if !matches.is_empty() {
            run_git(paths, &["--unset-all", INCLUDE_KEY])?;
        }
        run_git(
            paths,
            &["--add", INCLUDE_KEY, path.to_string_lossy().as_ref()],
        )?;
        true
    };
    Ok(InstallOutcome {
        file_changed,
        include_changed,
    })
}

/// Remove only the include entry whose value is ghis's own path, then delete
/// the generated file.  Returns whether anything was removed.
pub fn uninstall(paths: &ConfigPaths) -> Result<bool> {
    let path = baseline_path(paths);
    let matches = includes(paths, &path)?;
    let mut changed = false;
    if !matches.is_empty() {
        // `--fixed-value` plus the exact path removes only ghis's own entries.
        run_git(
            paths,
            &[
                "--fixed-value",
                "--unset-all",
                INCLUDE_KEY,
                path.to_string_lossy().as_ref(),
            ],
        )?;
        changed = true;
    }
    match fs::remove_file(&path) {
        Ok(()) => changed = true,
        Err(error) if error.kind() == io::ErrorKind::NotFound => {}
        Err(error) => return Err(error.into()),
    }
    Ok(changed)
}

/// Rewrite the generated file if the baseline include is installed.  Used by
/// `ghis sync`; an uninstalled baseline stays absent.
pub fn refresh(paths: &ConfigPaths) -> Result<bool> {
    if !status(paths)?.installed() {
        return Ok(false);
    }
    Ok(install(paths)?.file_changed)
}

/// Values of the global `include.path` entries that resolve to `target`.
fn includes(paths: &ConfigPaths, target: &Path) -> Result<Vec<String>> {
    let output = git::run_git(
        workdir(paths),
        ["config", "--global", "--null", "--get-all", INCLUDE_KEY],
    )
    .map_err(|error| BaselineError::Git {
        operation: "config --global --get-all include.path".into(),
        detail: error.to_string(),
    })?;
    if output.status.code() == Some(1) {
        return Ok(Vec::new());
    }
    if !output.status.success() {
        return Err(BaselineError::Git {
            operation: "config --global --get-all include.path".into(),
            detail: sanitized_stderr(&output),
        });
    }
    let expected = comparable(target);
    let values = output
        .stdout
        .split(|byte| *byte == 0)
        .map(|value| String::from_utf8_lossy(value).into_owned())
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    Ok(values
        .into_iter()
        .filter(|value| comparable(Path::new(value)) == expected)
        .collect())
}

/// Git stores the path exactly as given.  Compare expanded paths so a manual
/// `~/...` entry and ghis's absolute path count as the same include.
fn comparable(path: &Path) -> PathBuf {
    crate::signing::expand_user(path)
}

fn run_git(paths: &ConfigPaths, arguments: &[&str]) -> Result<()> {
    let output = git::run_git(
        workdir(paths),
        std::iter::once("config")
            .chain(std::iter::once("--global"))
            .chain(arguments.iter().copied()),
    )
    .map_err(|error| BaselineError::Git {
        operation: format!("config --global {}", arguments.join(" ")),
        detail: error.to_string(),
    })?;
    // Exit 5 means "you are trying to unset a value that is not there"; that is
    // the desired end state for uninstall and must not fail the command.
    if output.status.success() || output.status.code() == Some(5) {
        return Ok(());
    }
    Err(BaselineError::Git {
        operation: format!("config --global {}", arguments.join(" ")),
        detail: sanitized_stderr(&output),
    })
}

fn workdir(paths: &ConfigPaths) -> &Path {
    if paths.config_dir.is_dir() {
        &paths.config_dir
    } else {
        Path::new(".")
    }
}

fn sanitized_stderr(output: &std::process::Output) -> String {
    crate::diagnostics::sanitize_external_output(&String::from_utf8_lossy(&output.stderr))
}

fn write_atomically(path: &Path, content: &str) -> io::Result<()> {
    let temporary = path.with_extension(format!("gitconfig.{}.tmp", std::process::id()));
    fs::write(&temporary, content)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(&temporary, fs::Permissions::from_mode(0o600))?;
    }
    fs::rename(&temporary, path)
}
